use super::{source,grant,close_source,observe};
use crate::retained::{RetainedDiffFragment,RetainedDiffApply,RetainedDiffPreflightAdvance,RetainedDiffPreflightStep,retained_diff_birth_demand,begin_retained_diff,preflight_retained_diff,commit_retained_diff};
use crate::{ApplyCapability,MutationMessage};
use semio_framework_value::{NativeDecodeControl,RetirementDemand,ValueError,retirement::{RetireOwned,shared::sealed::SealedShared},native_decoding::owned::NativeIntrinsicSharedField,retained_clone::{RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedCloneClose}};
use std::{cell::Cell,mem::{ManuallyDrop,size_of}};
#[derive(semio_framework_value::RetireOwned)]
struct Diff{text:String}
#[derive(semio_framework_value::RetireOwned)]
struct Projection{text:Option<SealedShared<String>>}
struct Apply{field:NativeIntrinsicSharedField<String>,staged:ManuallyDrop<Option<SealedShared<String>>>,retirement:RetainedCloneClose,ready:bool,closing:bool,ledger:Option<u64>}
#[derive(Default)]
struct Recipient{calls:usize,bytes:usize}
struct RejectRecipient(Recipient);
impl semio_framework_value::native_decoding::NativeDecodeConstructionRecipient for RejectRecipient{
 fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{self.0.grant(d)}
 fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{self.0.accept(g,p)?;Err(ValueError::literal(semio_framework_value::ValueRefusalKind::WorkLimit,"original fixture rejects its accepted construction receipt"))}
}
impl semio_framework_value::native_decoding::NativeDecodeConstructionRecipient for Recipient{
 fn grant(&mut self,_:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{Ok(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64})}
 fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{assert!(p.fits(g));self.calls+=1;self.bytes+=p.retained_capacity_bytes;Ok(())}
}
impl RetainedDiffFragment<Projection> for Diff{type FragmentApply=Apply;}
impl RetainedDiffApply<Projection,Diff> for Apply{
 fn new()->Self{Self{field:Default::default(),staged:ManuallyDrop::new(None),retirement:Default::default(),ready:false,closing:false,ledger:None}}
 fn preflight_demand(&self,d:RetainedCloneRef<'_,Diff>,_:RetainedCloneRef<'_,Projection>,_:&Projection,body:usize)->Result<RetirementDemand,ValueError>{if self.field.ready(){self.field.take_demand()}else{self.field.demands(d.project(0,|d|&d.text),body)}}
 fn preflight(&mut self,d:RetainedCloneRef<'_,Diff>,p:RetainedCloneRef<'_,Projection>,post:&Projection,body:usize,g:RetainedCloneGrant,receiving:&mut NativeDecodeControl<'_>)->Result<RetainedDiffPreflightAdvance,ValueError>{let quote=self.preflight_demand(d,p,post,body)?;if !crate::retained_mutation_demand_fits(quote,g){return Ok(RetainedDiffPreflightAdvance::Progress(Default::default()));}if let Some(ledger)=self.ledger{assert_eq!(ledger,receiving.ledger_identity());}else{self.ledger=Some(receiving.ledger_identity());}if self.field.ready(){let(value,p)=self.field.take(g)?.unwrap();*self.staged=Some(value);self.ready=true;Ok(RetainedDiffPreflightAdvance::Ready(p,true))}else{self.field.advance(d.project(0,|d|&d.text),receiving,body,g).map(|s|RetainedDiffPreflightAdvance::Progress(s.progress()))}}
 fn take_messages(&mut self)->Vec<MutationMessage>{Vec::new()}
 fn commit_demand(&self,_:RetainedCloneRef<'_,Diff>,_:RetainedCloneRef<'_,Projection>,_:&Projection,_:usize)->Result<RetirementDemand,ValueError>{assert!(self.ready);Ok(RetirementDemand{copy_bytes:size_of::<Option<SealedShared<String>>>()*3,depth:1,..Default::default()})}
 fn commit(&mut self,d:RetainedCloneRef<'_,Diff>,p:RetainedCloneRef<'_,Projection>,post:&mut Projection,g:RetainedCloneGrant,_:ApplyCapability)->Result<RetainedCloneStep,ValueError>{let demand=self.commit_demand(d,p,post,g.maximum_copy_bytes)?;if !crate::retained_mutation_demand_fits(demand,g){return Ok(RetainedCloneStep::Progress(Default::default()));}std::mem::swap(&mut*self.staged,&mut post.text);Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()}))}
 fn begin_close(&mut self){self.closing=true;self.field.begin_close();}
 fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.field.terminal_is_empty(){self.field.close_demands(body)}else{self.retirement.next_owner_demands::<SealedShared<String>>(self.staged.is_some(),&None,body)}}
 fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{assert!(self.closing);if !self.field.terminal_is_empty(){return self.field.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()));}if !self.retirement.is_empty(){return self.retirement.step_granted(g).map(|s|RetainedCloneStep::Progress(s.progress()));}let step=self.retirement.begin_granted(&mut self.staged,g)?.unwrap_or(RetainedCloneStep::Complete(Default::default()));Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(step.progress())}else{RetainedCloneStep::Progress(step.progress())})}
 fn terminal_is_empty(&self)->bool{self.closing&&self.field.terminal_is_empty()&&self.staged.is_none()&&self.retirement.is_empty()}
}
fn cancel_prefixes(f:&serde_json::Value){
 for cut in [0,1,2,4,8,16,32,64]{
  let cancelled=Cell::new(false);let callbacks=Cell::new(0);let mut callback=|_:semio_framework_value::NativeDecodeProgress|{callbacks.set(callbacks.get()+1);!cancelled.get()};let mut receiving=NativeDecodeControl::new(f["maximumOwned"].as_u64().unwrap()as usize,&mut callback);let mut recipient=Recipient::default();let mut d=source(Diff{text:f["text"].as_str().unwrap().into()});let mut original=source(Projection{text:None});let post=Projection{text:None};let(mut owner,_)=begin_retained_diff::<Projection,Diff>(grant(retained_diff_birth_demand::<Projection,Diff>())).unwrap();
  for turn in 0..128{if turn==cut{cancelled.set(true);}let g=grant(owner.preflight_demand(d.borrow(),original.borrow(),&post,4096).unwrap());let(result,h)=observe(||receiving.with_construction_recipient(&mut recipient,|receiving|preflight_retained_diff(&mut owner,d.borrow(),original.borrow(),&post,4096,g,receiving)));match result{Err(error)=>{assert_eq!(error.kind,semio_framework_value::ValueRefusalKind::Canceled);assert_eq!(h,(error.retained_progress().retained_capacity_bytes,error.retained_progress().released_bytes));break;},Ok(step)=>{assert_eq!(h,(step.progress().retained_capacity_bytes,step.progress().released_bytes));if matches!(step,RetainedDiffPreflightStep::Admitted(..)){break;}}}}
  owner.begin_close();while !owner.terminal_is_empty(){let g=grant(owner.close_demand(4096).unwrap());let(step,h)=observe(||owner.close_step(g).unwrap());assert_eq!(h,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(post.text.is_none());assert_eq!(d.borrow().get().text,f["text"].as_str().unwrap());assert!(original.borrow().get().text.is_none());close_source(&mut d);close_source(&mut original);
 }
}
fn rejected_original_construction(f:&serde_json::Value){
 let mut callback=|_:semio_framework_value::NativeDecodeProgress|true;let mut receiving=NativeDecodeControl::new(f["maximumOwned"].as_u64().unwrap()as usize,&mut callback);let mut recipient=RejectRecipient(Recipient::default());let mut d=source(Diff{text:f["text"].as_str().unwrap().into()});let mut original=source(Projection{text:None});let post=Projection{text:None};let(mut owner,_)=begin_retained_diff::<Projection,Diff>(grant(retained_diff_birth_demand::<Projection,Diff>())).unwrap();let mut refused=false;
 for _ in 0..128{let g=grant(owner.preflight_demand(d.borrow(),original.borrow(),&post,4096).unwrap());let(result,h)=observe(||receiving.with_construction_recipient(&mut recipient,|receiving|preflight_retained_diff(&mut owner,d.borrow(),original.borrow(),&post,4096,g,receiving)));match result{Ok(step)=>assert_eq!(h,(step.progress().retained_capacity_bytes,step.progress().released_bytes)),Err(error)=>{assert_eq!(error.kind,semio_framework_value::ValueRefusalKind::WorkLimit);assert_eq!(error.retained_progress().retained_capacity_bytes,f["sealedBytes"].as_u64().unwrap()as usize);assert_eq!(h,(error.retained_progress().retained_capacity_bytes,error.retained_progress().released_bytes));refused=true;break;}}}assert!(refused);assert_eq!(recipient.0.calls,1);assert!(post.text.is_none());owner.begin_close();while !owner.terminal_is_empty(){let g=grant(owner.close_demand(4096).unwrap());let(step,h)=observe(||owner.close_step(g).unwrap());assert_eq!(h,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert_eq!(d.borrow().get().text,f["text"].as_str().unwrap());close_source(&mut d);close_source(&mut original);eprintln!("[DEBUG] original recipient refused after actual40-byte seal; central error kept exact born receipt once and cancelled physical output");
}
#[test]
fn retained_central_diff_forwards_actual_original_receiving_control_and_ledger(){let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let calls=Cell::new(0);let cancel=Cell::new(false);let mut callback=|_:semio_framework_value::NativeDecodeProgress|{calls.set(calls.get()+1);!cancel.get()};let mut receiving=NativeDecodeControl::new(f["maximumOwned"].as_u64().unwrap()as usize,&mut callback);receiving.charge(f["initialOwned"].as_u64().unwrap()as usize).unwrap();let ledger=receiving.ledger_identity();let mut recipient=Recipient::default();let mut d=source(Diff{text:f["text"].as_str().unwrap().into()});let mut original=source(Projection{text:None});let mut post=Projection{text:None};let(mut owner,_)=begin_retained_diff::<Projection,Diff>(grant(retained_diff_birth_demand::<Projection,Diff>())).unwrap();loop{let g=grant(owner.preflight_demand(d.borrow(),original.borrow(),&post,4096).unwrap());let before=calls.get();let(s,h)=observe(||receiving.with_construction_recipient(&mut recipient,|receiving|preflight_retained_diff(&mut owner,d.borrow(),original.borrow(),&post,4096,RetainedCloneGrant{maximum_items:0,..g},receiving)).unwrap());assert_eq!(s.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(calls.get(),before);let(s,h)=observe(||receiving.with_construction_recipient(&mut recipient,|receiving|preflight_retained_diff(&mut owner,d.borrow(),original.borrow(),&post,4096,g,receiving)).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));assert_eq!(receiving.ledger_identity(),ledger);match s{RetainedDiffPreflightStep::Admitted(_,messages)=>{assert!(messages.is_empty());break;},RetainedDiffPreflightStep::Progress(_)=>{},_=>panic!("original controlled receiving refused")}}assert_eq!(receiving.owned_bytes(),f["expected"]["finalOwned"].as_u64().unwrap()as usize);let g=grant(owner.commit_demand(d.borrow(),original.borrow(),&post,4096).unwrap());commit_retained_diff(&mut owner,d.borrow(),original.borrow(),&mut post,g).unwrap();assert_eq!(post.text.as_ref().unwrap().as_str(),f["text"].as_str().unwrap());owner.begin_close();while !owner.terminal_is_empty(){let g=grant(owner.close_demand(4096).unwrap());owner.close_step(g).unwrap();}close_source(&mut d);close_source(&mut original);let mut close=semio_framework_value::retirement::controlled::ControlledRetirement::new(post).unwrap_or_else(|_|panic!("actual post closure"));while !close.terminal_is_empty(){let g=grant(close.next_demand(4096).unwrap());close.step(g).unwrap();}assert_eq!(recipient.calls,1);assert_eq!(recipient.bytes,f["sealedBytes"].as_u64().unwrap()as usize);cancel_prefixes(&f);rejected_original_construction(&f);assert!(calls.get()>1);eprintln!("[DEBUG] central retained receiving originalLedger={ledger} cumulativeOwned={} deniedCallbackCalls=0 foreignControlCalls=0",receiving.owned_bytes());}
